async function stitchPdfAttachments(doc, inserts) {
	const raw = doc.output("arraybuffer");
	if (!inserts.length) return new Blob([raw], { type: "application/pdf" });
	const base = await PDFDocument.load(raw);
	const ordered = inserts.slice().sort((a, b) => b.page - a.page);
	for (const ins of ordered) try {
		const src = await PDFDocument.load(dataUrlToBytes(ins.dataUrl), { ignoreEncryption: true });
		const copied = await base.copyPages(src, src.getPageIndices());
		const at = Math.max(0, ins.page - 1);
		if (at < base.getPageCount()) base.removePage(at);
		copied.forEach((page, i) => base.insertPage(Math.min(at + i, base.getPageCount()), page));
	} catch {}
	const bytes = await base.save();
	return new Blob([bytes], { type: "application/pdf" });
}
function pdfHandle(blob) {
	return {
		output(type) {
			if (type === "blob") return blob;
			return URL.createObjectURL(blob);
		},
		save(filename) {
			const url = URL.createObjectURL(blob);
			const a = document.createElement("a");
			a.href = url;
			a.download = filename;
			document.body.appendChild(a);
			a.click();
			a.remove();
			setTimeout(() => URL.revokeObjectURL(url), 1500);
		}
	};
}
function stampDraftWatermark(doc) {
	if (!doc || typeof doc.getNumberOfPages !== "function") return;
	const total = doc.getNumberOfPages();
	for (let i = 1; i <= total; i++) {
		doc.setPage(i);
		const pageW = doc.internal.pageSize.getWidth();
		const pageH = doc.internal.pageSize.getHeight();
		const body = doc.getFont()?.fontName || "helvetica";
		let pushed = false;
		try {
			if (typeof doc.saveGraphicsState === "function") {
				doc.saveGraphicsState();
				pushed = true;
			}
			if (typeof doc.GState === "function" && typeof doc.setGState === "function") doc.setGState(new doc.GState({ opacity: 0.16 }));
		} catch { /* draw the mark even if opacity is unavailable */ }
		try {
			doc.setFont(body, "bold");
		} catch {
			try { doc.setFont(body, "normal"); } catch { /* keep the current font */ }
		}
		doc.setFontSize(52);
		doc.setTextColor(170, 170, 170);
		try {
			doc.text("DRAFT", pageW / 2, pageH / 2, { align: "center", angle: 32 });
		} catch {
			doc.text("DRAFT", pageW / 2, pageH / 2, { align: "center" });
		}
		if (pushed) try { doc.restoreGraphicsState(); } catch { /* page state already restored */ }
		doc.setTextColor(0, 0, 0);
		try { doc.setFont(body, "normal"); } catch { /* keep the current font */ }
		doc.setFontSize(8);
	}
}
