function scheduleSpanDays(tasks) {
	const { taskSchedule } = computeSchedule(tasks || []);
	const vals = Object.values(taskSchedule || {});
	if (!vals.length) return 1;
	const starts = vals.map((s) => s.start);
	const ends = vals.map((s) => s.end);
	return Math.max(1, Math.max(...ends) - Math.min(...starts) + 1);
}
